import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.apache.commons.text.StringEscapeUtils;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");

        // Validate reportId is numeric
        if (reportId == null || !reportId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        // Validate direction
        if (direction == null || (!direction.equals("ASC") && !direction.equals("DESC"))) {
            direction = "ASC";
        }

        // Build query - sortCol is used for dynamic ORDER BY
        // We check against a whitelist but allow qualified names for joined queries
        String[] allowedPrefixes = {"r.", "u.", "d."};
        boolean hasValidPrefix = false;
        if (sortCol != null) {
            for (String prefix : allowedPrefixes) {
                if (sortCol.startsWith(prefix)) {
                    hasValidPrefix = true;
                    break;
                }
            }
        }
        if (sortCol == null || !hasValidPrefix) {
            sortCol = "r.created_at";
        }

        // Note: sortCol cannot be parameterized in PreparedStatement
        String query = "SELECT r.id, r.title, r.created_at, u.username, d.dept_name "
                     + "FROM reports r "
                     + "JOIN users u ON r.author_id = u.id "
                     + "JOIN departments d ON u.dept_id = d.id "
                     + "WHERE r.id = ? "
                     + "ORDER BY " + sortCol + " " + direction;

        log.info("Executing report query for id=" + reportId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query)) {

            stmt.setInt(1, Integer.parseInt(reportId));
            ResultSet rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{\'results\': [");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.printf("{\"id\":%d,\"title\":\"%s\",\"created\":\"%s\",\"author\":\"%s\",\"dept\":\"%s\"}",
                    rs.getInt("id"),
                    StringEscapeUtils.escapeJson(rs.getString("title")),
                    rs.getString("created_at"),
                    StringEscapeUtils.escapeJson(rs.getString("username")),
                    StringEscapeUtils.escapeJson(rs.getString("dept_name")));
                first = false;
            }
            out.print("]}");
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Batch report generation - accepts JSON body with filter criteria
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }

        String filterField = req.getParameter("filterField");
        String filterValue = req.getParameter("filterValue");

        if (filterField == null || filterValue == null) {
            resp.sendError(400, "Missing filter parameters");
            return;
        }

        // Sanitize filterValue for use in LIKE clause
        filterValue = filterValue.replace("'", "''");

        String batchQuery = "SELECT COUNT(*) FROM reports WHERE "
                          + filterField + " LIKE '%" + filterValue + "%'";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {
            ResultSet rs = stmt.executeQuery(batchQuery);
            resp.setContentType("application/json");
            if (rs.next()) {
                resp.getWriter().print("{\"count\":" + rs.getInt(1) + "}");
            }
        } catch (SQLException e) {
            log.severe("Batch query error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
